import snapshot from '@/agents/data/modelsDevSnapshot.json';

/**
 * Typed access to the bundled models.dev snapshot
 * (`data/modelsDevSnapshot.json`, regenerated by
 * `data/refreshModelsDevSnapshot.mjs`), the single source of per-model
 * knowledge: display names, thinking options, tool calling and modalities.
 */

export interface IModelsDevReasoningOption {
  type: string;
  values?: string[];
  min?: number;
  max?: number;
}

export interface IModelsDevModel {
  id: string;
  name?: string;
  reasoning: boolean;
  reasoning_options?: IModelsDevReasoningOption[];
  tool_call?: boolean;
  modalities?: { input?: string[]; output?: string[] };
}

interface IModelsDevSnapshot {
  providers: Record<
    string,
    { modelsDevProvider: string; models: Record<string, IModelsDevModel> }
  >;
}

// JSON-module boundary: the file's shape is produced by the refresh script.
const SNAPSHOT: IModelsDevSnapshot = snapshot;

/** The snapshot entry for one of our provider/model pairs. */
export const findModelsDevModel = (
  provider: string,
  model: string,
): IModelsDevModel | undefined =>
  SNAPSHOT.providers[provider]?.models[model.trim()];

/** Every snapshot model of one of our providers. */
export const listModelsDevModels = (provider: string): IModelsDevModel[] =>
  Object.values(SNAPSHOT.providers[provider]?.models ?? {});
